"""Generate the sorted HTML5 named-reference table from CPython html.entities."""
from html.entities import html5
from pathlib import Path


def rust_string(value: str) -> str:
    return '"' + "".join(f"\\u{{{ord(char):x}}}" for char in value) + '"'


def main() -> None:
    destination = Path(__file__).resolve().parents[1] / "crates/core/src/markup/html_entities.rs"
    lines = [
        "// Generated by scripts/generate_html_entities.py from CPython html.entities.html5.",
        "// HTML5 named character references, including legacy names without semicolons.",
        "pub(super) const NAMED_ENTITIES: &[(&str, &str)] = &[",
    ]
    lines.extend(f'    ("{name}", {rust_string(value)}),' for name, value in sorted(html5.items()))
    lines.append("];")
    destination.write_text("\n".join(lines) + "\n", encoding="utf8")
    print(f"Generated {len(html5)} references in {destination}")


if __name__ == "__main__":
    main()
